-- Weekly reports and the coach's read-only share link.

create table public.weekly_reports (
  user_id uuid not null default auth.uid() references auth.users on delete cascade,
  week_start date not null,
  -- Numbers computed by the app (src/lib/report.ts).
  stats jsonb not null,
  -- Maia's write-up: summary, wins, watch-outs, next-week focus.
  narrative jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, week_start)
);

-- One share link per user. The token is random and generated by the app;
-- replacing it makes the old link stop working.
create table public.coach_shares (
  user_id uuid primary key default auth.uid() references auth.users on delete cascade,
  token text not null unique check (length(token) >= 40),
  created_at timestamptz not null default now()
);

alter table public.weekly_reports enable row level security;
alter table public.coach_shares enable row level security;

create policy "Own weekly reports" on public.weekly_reports for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "Own coach share" on public.coach_shares for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create trigger touch before update on public.weekly_reports
  for each row execute function public.touch_updated_at();

-- What the coach link shows, looked up by token. Runs with the owner's
-- rights so the coach needs no account, but returns only this read-only
-- view: goal, recent plans (no Maia chat), check-ins and reports.
create function public.coach_view(p_token text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  uid uuid;
begin
  select user_id into uid from public.coach_shares where token = p_token;
  if uid is null then
    return null;
  end if;
  return jsonb_build_object(
    'goal', (select goal_input from public.profiles where user_id = uid),
    'weeks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'week_start', w.week_start, 'phases', w.phases, 'mode', w.mode, 'plan', w.plan
      ) order by w.week_start desc)
      from (select * from public.week_plans where user_id = uid order by week_start desc limit 6) w
    ), '[]'::jsonb),
    'logs', coalesce((
      select jsonb_object_agg(d.date, jsonb_build_object('checkIns', d.check_ins, 'extras', d.extras))
      from public.day_logs d
      where d.user_id = uid and d.date >= current_date - 56
    ), '{}'::jsonb),
    'reports', coalesce((
      select jsonb_agg(jsonb_build_object(
        'week_start', r.week_start, 'stats', r.stats, 'narrative', r.narrative, 'updated_at', r.updated_at
      ) order by r.week_start desc)
      from (select * from public.weekly_reports where user_id = uid order by week_start desc limit 12) r
    ), '[]'::jsonb)
  );
end;
$$;

revoke all on function public.coach_view(text) from public;
grant execute on function public.coach_view(text) to anon, authenticated;
